<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$errors=[];$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){ $data=['full_name'=>trim($_POST['full_name']??''),'email'=>trim($_POST['email']??''),'password'=>$_POST['password']??'']; if($data['full_name']==='')$errors[]='Full name is required'; if(!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors[]='Valid email is required'; if(strlen($data['password'])<6)$errors[]='Password must be at least 6 characters'; if(!$errors){$r=$auth->register($data);if($r['success'])$ok=$r['message'];else $errors[]=$r['message'];}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5" style="max-width:600px"><div class="card shadow"><div class="card-body p-4"><h2>Create Passenger Account</h2><?php foreach($errors as $e):?><div class="alert alert-danger"><?=htmlspecialchars($e)?></div><?php endforeach;?><?php if($ok):?><div class="alert alert-success"><?=htmlspecialchars($ok)?> <a href="login.php">Login</a></div><?php endif;?><form method="post"><label class="form-label">Full name</label><input class="form-control mb-3" name="full_name" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" minlength="6" required><button class="btn btn-primary w-100">Register</button></form><a class="d-block mt-3" href="login.php">Already have an account?</a></div></div></div></body></html>